import{_ as s,H as t,f as a,i as n}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"05 | 协议实战（下）：通过A2A，你的智能体不仅能对话还可以协作！","description":"","frontmatter":{},"headers":[{"level":2,"title":"项目准备工作","slug":"项目准备工作","link":"#项目准备工作","children":[{"level":3,"title":"安装 Python3.12 版本","slug":"安装-python3-12-版本","link":"#安装-python3-12-版本","children":[]},{"level":3,"title":"克隆项目代码库","slug":"克隆项目代码库","link":"#克隆项目代码库","children":[]},{"level":3,"title":"Google API key","slug":"google-api-key","link":"#google-api-key","children":[]}]},{"level":2,"title":"启动 A2A Demo 项目","slug":"启动-a2a-demo-项目","link":"#启动-a2a-demo-项目","children":[]},{"level":2,"title":"A2A Demo 的设计实现","slug":"a2a-demo-的设计实现","link":"#a2a-demo-的设计实现","children":[{"level":3,"title":"UI  层入口与服务注册","slug":"ui-层入口与服务注册","link":"#ui-层入口与服务注册","children":[]},{"level":3,"title":"Host Agent 服务实现","slug":"host-agent-服务实现","link":"#host-agent-服务实现","children":[]},{"level":3,"title":"Host Agent  调度与 A2A 协议实现","slug":"host-agent-调度与-a2a-协议实现","link":"#host-agent-调度与-a2a-协议实现","children":[]},{"level":3,"title":"Remote Agents 和 Agent Card","slug":"remote-agents-和-agent-card","link":"#remote-agents-和-agent-card","children":[]},{"level":3,"title":"A2A Client  端实现","slug":"a2a-client-端实现","link":"#a2a-client-端实现","children":[]}]},{"level":2,"title":"总结一下","slug":"总结一下","link":"#总结一下","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"MCP&A2A前沿实战/05｜协议实战（下）：通过A2A，你的智能体不仅能对话还可以协作！.md","filePath":"MCP&A2A前沿实战/05｜协议实战（下）：通过A2A，你的智能体不仅能对话还可以协作！.md","lastUpdated":1795531178000}'),i={name:"MCP&A2A前沿实战/05｜协议实战（下）：通过A2A，你的智能体不仅能对话还可以协作！.md"};function p(l,e,o,g,r,h){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="_05-协议实战-下-通过a2a-你的智能体不仅能对话还可以协作" tabindex="-1">05 | 协议实战（下）：通过A2A，你的智能体不仅能对话还可以协作！ <a class="header-anchor" href="#_05-协议实战-下-通过a2a-你的智能体不仅能对话还可以协作" aria-label="Permalink to &quot;05 | 协议实战（下）：通过A2A，你的智能体不仅能对话还可以协作！&quot;">​</a></h1><p>你好，我是黄佳。</p><p>上节课我们完成了快速搭建 MCP RAG 服务，这节课我们继续进行协议实战，感受一下 A2A的协议用法。</p><p>下面我将逐步给你展示一个通过 A2A 协议搭建的智能体平台，让你的智能体不仅能够相互对话，还能够协作协力来完成一个任务。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/1.png" alt=""></a></p><ul><li>A2A Demo 系统架构图 图源：<a href="https://github.com/google-a2a/a2a-samples/tree/main/demo" target="_blank" rel="noreferrer">https://github.com/google-a2a/a2a-samples/tree/main/demo</a></li></ul><p>在这个基于 A2A 协议的智能体平台中，用户在浏览器端发出指令后，前端会将该请求传给Host Agent，由它负责解析用户意图、拆解具体子任务，并且并行触发多个 Remote Agent；每个 Remote Agent 通过 A2A Client 将子任务封装为标准的 JSON-RPC 请求，发送给远端对应的 A2A Server，再由后者调用各自擅长的智能体模块（如 LangGraph Agent 负责外汇兑换、Google ADK Agent 负责报销收据、Crew AI Agent 负责根据文字内容来生成图片等）执行并返回结果；最后，Host Agent 汇总并格式化各路反馈，一并呈现给用户，实现多智能体的分工协作与能力互补。</p><h2 id="项目准备工作" tabindex="-1">项目准备工作 <a class="header-anchor" href="#项目准备工作" aria-label="Permalink to &quot;项目准备工作&quot;">​</a></h2><p>我们先来搞定一些必要的准备工作。</p><h3 id="安装-python3-12-版本" tabindex="-1">安装 Python3.12 版本 <a class="header-anchor" href="#安装-python3-12-版本" aria-label="Permalink to &quot;安装 Python3.12 版本&quot;">​</a></h3><p>A2A 协议非常新，所以它对环境的要求也是很高的。因此，要确保我们已经安装了 Python3.12 版本。如果你的系统没有这个版本，那就要更新一下。</p><p>下面是在 Ubuntu 系统中更新 Python 的代码示例：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sudo apt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">update</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sudo apt install software</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">properties</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">common</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sudo </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">apt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repository ppa:deadsnakes</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ppa</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sudo apt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">update</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sudo apt install </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">python3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> python3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">venv </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">python3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dev</span></span></code></pre></div><p>在 Ubuntu 系统中，检查 Python 3.12 是否安装成功：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3.12 --version</span></span>
<span class="line"><span>Python 3.12.10</span></span></code></pre></div><p>其他各种系统的版本安装我就不赘述了。</p><h3 id="克隆项目代码库" tabindex="-1">克隆项目代码库 <a class="header-anchor" href="#克隆项目代码库" aria-label="Permalink to &quot;克隆项目代码库&quot;">​</a></h3><p>安装好 Python 包之后，就可以来到这里下载我为你准备的这套 A2A Demo 代码，并用下面的命令把它 Clone 到你的本机。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/huangjia2019/a2a-in-action.git</span></span></code></pre></div><p>这一套代码，是我基于 Google 官方 A2A 仓库复制出来并简单改造过的教学版本，我会基于这套代码为你详细讲解 A2A 协议的实现细节。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/2.png" alt=""></a></p><p>项目克隆到本机之后呢，你会看下面的目录结构。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/3.png" alt=""></a></p><p>其中 agents 目录中，就包含后续课程中要讲解的一系列 A2A Agents 示例。而 Demo 目录则是我们下面要演示的协议实战示例。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/4.png" alt=""></a></p><p>我们打开 demo 目录，再打开其中的 ui 目录，你会注意到其中有一个 pyproject.toml 文件。这是一个供 UV 使用的 Python 项目的环境配置文件，主要用于定义项目的元数据、依赖、构建方式等（其实，每一个 Agent 目录中，以及项目的根目录中，都会有这样一个配置文件，因为每一个 Agent 服务所需要的环境各不相同）。</p><h3 id="google-api-key" tabindex="-1">Google API key <a class="header-anchor" href="#google-api-key" aria-label="Permalink to &quot;Google API key&quot;">​</a></h3><p>这个项目以及后续要学习的许多 Agents 都需要一个 Google API key，我们可以通过这个链接创建一个，并通过.env 来配置这个密钥，提供给程序使用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/5.png" alt=""></a></p><p>可以把这个.env 文件放置在 A2A-IN-ACTION 项目根目录下。</p><p>好，下面就可以启动这个 A2A 项目并展示 Agents 之间的通信能力了。</p><h2 id="启动-a2a-demo-项目" tabindex="-1">启动 A2A Demo 项目 <a class="header-anchor" href="#启动-a2a-demo-项目" aria-label="Permalink to &quot;启动 A2A Demo 项目&quot;">​</a></h2><p>先通过 cd demo/ui 命令进入 A2A Demo 项目的目录。</p><p>使用下面的命令来启动这个 Demo。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uv run main.py</span></span></code></pre></div><p>在第一次启动的同时，uv 命令会安装一系列所需的包。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/6.png" alt=""></a></p><p>同时，应用程序将成功在 12000 端口启动。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/7.png" alt=""></a></p><p>你将看到如下所示的和 Agent 交互对话的窗口。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/8.png" alt=""></a></p><p>而你的 A2A Demo 应用也能够接收到你的对话，服务顺畅地跑起来了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/9.png" alt=""></a></p><p>选择最下面的 Setting 按钮，我们先设置一下 Google API Key（相当于又手工设置了环境变量GOOGLE_API_KEY），同时选择接收图文输出。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/10.png" alt=""></a></p><p>此时，你可以顺畅地和 Host 进行对话，在这个 Chat 窗口后面，系统内部其实是有一个名叫“Simple Agent”的简单智能体（Host Agent 或叫做 Local Agent）负责和我们对话。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/11.png" alt=""></a></p><p>当然，这个简单智能体的能力有限。比如当我问他“如何把 20 欧元转换成美元”，他说他没有能力查找汇率。当我让它列出智能体的列表，它说目前这个应用中找不到任何外部智能体。其中，目前应用程序中只有它这一个 Local Agent，看起来它的能力也仅限于陪聊。</p><p>就像 MCP Host 也要进行一些配置，才能够连接到外部的 MCP 服务，看来我们也需要进行一些配置，才能够调用其他 Agent 的能力。</p><p>下面，我们就选择 Agents 选项卡，来配置一系列的 Remote Agents，也就是外部 Agents。我们先来添加一个 Currency Agent。</p><p>首先，进入 agents/langgraph 目录，然后通过 uv run . 命令把这个 Agent 服务跑起来。——这是一个专门负责汇率计算的 Agent，能够实时的访问各种国家的货币汇率信息。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/12.png" alt=""></a></p><p>好，此时远程 Agent 服务中，我们可以在应用中添加这个 Currency Agent 了！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/13.png" alt=""></a></p><p>选择 Agent 的名称和端口，添加好的 Agent 如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/14.png" alt=""></a></p><p>重新开始对话，你就能发现，这时候 Local Agent 遇到货币兑换这样的难题就不会再捉襟见肘了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/15.png" alt=""></a></p><p>几轮对话过后，选择 Task List 选项卡，可以看到一系列的对话列表。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/16.png" alt=""></a></p><p>此时，在服务器的后台，我们也可以看到 Local Host 和远程服务的交互过程。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/17.png" alt=""></a></p><p>好，那么现在我们看到了一个 Local Agent（也叫 Host Agent，即本地 Agent），通过 A2A 协议调用了外部 Agent 的能力。底层是如何实现的？让我们来一起剖析一下关键设计。</p><h2 id="a2a-demo-的设计实现" tabindex="-1">A2A Demo 的设计实现 <a class="header-anchor" href="#a2a-demo-的设计实现" aria-label="Permalink to &quot;A2A Demo 的设计实现&quot;">​</a></h2><p>从整体架构上看，一个 A2A 系统由以下主要组件构成：</p><ul><li><p>Agent Card: 代理的身份标识和能力声明。</p></li><li><p>Skill: 代理可执行的具体能力。</p></li><li><p>Task Manager: 处理任务流和状态管理。</p></li><li><p>Server: 提供 HTTP 接口让其他代理 / 客户端访问。</p></li></ul><p>而在这些关键组件实现的基础之上，还需要为 Demo 应用创建 UI，并注册服务，还要通过一系列的通信机制让外部 Agent 和 Host Agent（本地 Agent）能够相互对话，进行能力的发现。</p><h3 id="ui-层入口与服务注册" tabindex="-1">UI 层入口与服务注册 <a class="header-anchor" href="#ui-层入口与服务注册" aria-label="Permalink to &quot;UI  层入口与服务注册&quot;">​</a></h3><p>首先我们简单介绍 UI 层的实现。在文件夹 demo/ui/pages.py 中，就这个应用的前端页面。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/18.png" alt=""></a></p><p>文件 demo/ui/main.py 中通过 FastAPI 启动后端服务，并用 Mesop 框架组织前端页面。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> from service.server.server import ConversationServer</span></span>
<span class="line"><span> ...</span></span>
<span class="line"><span> app = FastAPI()</span></span>
<span class="line"><span> router = APIRouter()</span></span>
<span class="line"><span> agent_server = ConversationServer(router)</span></span>
<span class="line"><span> app.include_router(router)</span></span></code></pre></div><p>这段代码将所有与智能体对话相关的 API 路由注册到 FastAPI 应用，核心逻辑都在ConversationServer 里。</p><h3 id="host-agent-服务实现" tabindex="-1">Host Agent 服务实现 <a class="header-anchor" href="#host-agent-服务实现" aria-label="Permalink to &quot;Host Agent 服务实现&quot;">​</a></h3><p>前端服务需要首先和本地 Agent 建立连接，才能实现和用户的交互对话。文件demo/ui/service/server/server.py 中的 ConversationServer 类是 UI 与 Host Agent 之间的桥梁，负责路由注册和请求分发。初始化时会根据环境变量选择 ADKHostManager（真实多智能体调度）或 InMemoryFakeAgentManager（假数据）。</p><p>此处的关键方法是:</p><ul><li><p>async def _send_message(self, request: Request)，它接收前端消息，调用self.manager.process_message(message) 进行处理（异步线程），并返回消息 ID。</p></li><li><p>async def _register_agent(self, request: Request)，支持动态注册远程 Agent，调用self.manager.register_agent(url)。</p></li><li><p>async def _list_agents(self)，返回当前已注册的所有 Agent 信息。</p></li></ul><p>这些 API 接口就是 A2A 协议在本地 Host 侧的“落地实现”，所有对话、任务、Agent 管理都通过这里转发。</p><h3 id="host-agent-调度与-a2a-协议实现" tabindex="-1">Host Agent 调度与 A2A 协议实现 <a class="header-anchor" href="#host-agent-调度与-a2a-协议实现" aria-label="Permalink to &quot;Host Agent  调度与 A2A 协议实现&quot;">​</a></h3><p>下面我们来分析本地 Agent 是如何实现 A2A 协议的。</p><p>在文件 demo/ui/service/server/adk_host_manager.py 中，ADKHostManager 继承自ApplicationManager，是真正的“智能体大脑”。</p><p>此处的关键属性和方法如下：</p><ul><li><p>self._host_agent = HostAgent([], self.task_callback)，这里的 HostAgent 是多智能体调度的核心，负责多智能体的注册、能力发现、任务分发、回调等，是 Host 侧的“大脑”。这个类的定义位于 hosts/multiagent/host_agent.py 文件。</p></li><li><p>async def process_message(self, message: Message)，处理用户消息，维护会话、消息、事件等，并通过 self._host_runner.run_async(…) 触发智能体推理和任务流转。</p></li><li><p>def register_agent(self, url)，支持通过 URL 动态注册远程 Agent，Agent 信息会被加入_agents 列表，供 Host 调度。</p></li><li><p>@property def agents(self)，返回所有已注册的 AgentCard（能力描述卡片），用于能力发现和展示。</p></li></ul><p>这里的 process_message 方法会将用户输入转为标准的 A2A 消息格式，交由 HostAgent进行多智能体协作处理，最终结果再通过事件流返回。</p><p>HostAgent 通过 remote_agent_connection.py 维护与每个远程 Agent 的连接和能力卡片（AgentCard）—— 这也是 A2A 协议的核心交互机制。</p><h3 id="remote-agents-和-agent-card" tabindex="-1">Remote Agents 和 Agent Card <a class="header-anchor" href="#remote-agents-和-agent-card" aria-label="Permalink to &quot;Remote Agents 和 Agent Card&quot;">​</a></h3><p>在 agent 目录中，有一系列可以配置到 Demo 应用中的外部（Remote）Agents，每个子目录就是一个外部 Agent 的实现。在刚才的 Demo 环节，我们以通过 LangGraph 实现的货币转换 Agent 为例，启动并手动注册了它。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/19.png" alt=""></a></p><p>具体来说：</p><ul><li><p>agents/langgraph/agent.py 中的 CurrencyAgent，用 LangGraph 框架和 Google GeminiAPI 实现了货币兑换的智能体逻辑，支持流式和同步调用。</p></li><li><p>agents/langgraph/main.py 中通过 A2AServer（A2A 协议服务端实现）将 CurrencyAgent以 HTTP 服务形式暴露出来，并注册了自己的 AgentCard，即能力卡片。</p></li></ul><p>Agent Card 是 A2A 协议的关键内核概念之一，它负责定义代理的元数据（名称、描述、URL、版本等），声明支持的输入 / 输出模态（如文本、图像等）同时列出代理提供的技能清单（skill），其目的是让你的代理能够被发现，并让其他系统知道如何与它交互。这是实现“代理之间互相通信”（Agent-to-Agent）的基础。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent_card = AgentCard(</span></span>
<span class="line"><span>   name=&#39;Currency Agent&#39;,</span></span>
<span class="line"><span>   description=&#39;Helps with exchange rates for currencies&#39;,</span></span>
<span class="line"><span>   url=f&#39;http://{host}:{port}/&#39;,</span></span>
<span class="line"><span>   version=&#39;1.0.0&#39;,</span></span>
<span class="line"><span>   defaultInputModes=CurrencyAgent.SUPPORTED_CONTENT_TYPES,</span></span>
<span class="line"><span>   defaultOutputModes=CurrencyAgent.SUPPORTED_CONTENT_TYPES,</span></span>
<span class="line"><span>   capabilities=capabilities,</span></span>
<span class="line"><span>   skills=[skill],</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>你可以把它想象成你的 AI 代理（Agent）的 “名片” 或 “说明书”。它是一个标准化的信息包（通常是 JSON 格式），用来告诉其他代理或系统这个代理叫什么名字（name）、它是干什么的（description）、在哪里可以找到它并与之通信（url，包含主机和端口）、它支持哪些基本能力（capabilities）、它具体能完成哪些任务或技能（skills，比如货币兑换服务），以及版本号、默认沟通方式等其他元数据。</p><p>A2AServer 则是 A2A 的协议服务端实现，其中的 Task Manager 负责任务生命周期管理，状态追踪和更新（WORKING、COMPLETED、ERROR 等），处理同步 / 异步请求（on_send_task 和 on_send_task_subscribe），生成适当的响应格式以及错误处理和恢复。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server = A2AServer(</span></span>
<span class="line"><span>     agent_card=agent_card,</span></span>
<span class="line"><span>     task_manager=AgentTaskManager(</span></span>
<span class="line"><span>         agent=CurrencyAgent(),</span></span>
<span class="line"><span>         notification_sender_auth=notification_sender_auth,</span></span>
<span class="line"><span>     ),</span></span>
<span class="line"><span>     host=host,</span></span>
<span class="line"><span>     port=port,</span></span>
<span class="line"><span> )</span></span></code></pre></div><p>这样，langgraph 目录下的 Agent 就成为了一个标准的 A2A 协议远程 Agent，具备独立服务能力和能力自描述。</p><h3 id="a2a-client-端实现" tabindex="-1">A2A Client 端实现 <a class="header-anchor" href="#a2a-client-端实现" aria-label="Permalink to &quot;A2A Client  端实现&quot;">​</a></h3><p>最后我们来看一下 A2A Client 端的实现逻辑。文件 demo/ui/service/client/client.py 中的ConversationClient 类封装了与远程 Agent 的 HTTP 通信，所有请求都以 JSON-RPC 格式发送。</p><p>此处的关键方法如下：</p><ul><li><p>async def send_message(self, payload: SendMessageRequest)，通过 HTTP POST 将消息发送到远程 Agent 的 /message/send 接口。</p></li><li><p>async def register_agent(self, payload: RegisterAgentRequest)，远程注册 Agent。</p></li></ul><p>其它如 list_agents、list_tasks、get_events 等，均为 A2A 协议的标准接口，负责 A2A 协议“客户端”的标准实现，并与远端 Agent 进行协议对接。</p><h2 id="总结一下" tabindex="-1">总结一下 <a class="header-anchor" href="#总结一下" aria-label="Permalink to &quot;总结一下&quot;">​</a></h2><p>好，总结一下。Google A2A 框架提供了一个灵活而标准化的通信机制，让各个 AI 代理能够基于面向技能的设计，通过清晰的身份标识和能力声明，以统一的协议实现同步或异步的交互，并在此过程中依赖完善的状态管理与错误处理，以模块化、可扩展的架构共同构建更复杂的应用场景。</p><p>在具体实现上，每个 Agent 启动时会生成自己的 AgentCard，内含名称、描述、服务 URL 以及所支持的能力和技能等关键信息；启动后，Agent 通过 A2A Server 将自己的 AgentCard 向注册中心登记，而 Host 端则通过注册 / 发现机制（如调用 demo/ui/utils/agent_card.py 中的get_agent_card 接口）远程拉取所有 AgentCard，实现能力路由与展示，从而完成代理之间的能力发现与互操作。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/20.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/05/20.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>请你研究一下 Agents 目录中的外部 Agents，每一个具有什么能力，能完成什么任务。</p></li><li><p>请你在这个应用程序中，添加更多的 Agent，让多个 Agent 协作完成更为复杂的任务，比如发票的报销工作。</p></li></ol><p>怎么样，这个应用像不像一个简版的 Manus，那么在后续 A2A 每一课的讲解中我们将更深入的剖析具体 agents 的设计以及 agents 之间是怎样交互和协调工作的，敬请期待。</p>`,108)])])}const E=s(i,[["render",p]]);export{c as __pageData,E as default};
